const mHam = document.querySelector('.m_ham');
const mNavWrap = document.querySelector('.m_nav-wrap');
let pageY;

const naviOpen =()=>{
    /*
        현재 페이지 스크롤 범위 저장
        .page-wrap top 값 변경
        body fixed 로 변경
    */
    pageY = window.pageYOffset;
    document.querySelector('.page-wrap').style.top = `-${pageY}px`;
    document.body.classList.add('fixed');

    mNavWrap.classList.add('is-active');

    gsap.killTweensOf('.m_ham > svg.line > rect')
    gsap.to( '.m_ham > svg.line:nth-child(1) > rect', .5, { rotation: 45, x:4, y:-4, fill: 'rgb(0,0,0)', ease: 'Quart.easeInOut' });
    gsap.to( '.m_ham > svg.line:nth-child(2) > rect' , .5, { rotation: -45, x:2.5, y:6, fill: 'rgb(0,0,0)', ease: 'Quart.easeInOut' });
}

const naviClose =(isTop)=>{
    /*
        body fixed 삭제
        .page-wrap top 복구
        페이지 스크롤 원위치
    */
    document.body.classList.remove('fixed');
    document.querySelector('.page-wrap').style.top = `-${0}px`;

    isTop ? window.scrollTo(0, 0) : window.scrollTo(0, pageY);

    mNavWrap.classList.remove('is-active');

    gsap.killTweensOf('.m_ham > svg.line > rect')
    gsap.to( '.m_ham > svg.line:nth-child(1) > rect', .4, { rotation: 0, x:0, y:0, fill: 'rgb(255,255,255)', ease: 'Quart.easeInOut', delay:0.1 });
    gsap.to( '.m_ham > svg.line:nth-child(2) > rect' , .4, { rotation: 0, x:0, y:0, fill: 'rgb(255,255,255)', ease: 'Quart.easeInOut', delay:0.1 });
}

mHam.addEventListener('click', (e)=>{
    e.preventDefault();
    mNavWrap.classList.toggle('is-open');
    mNavWrap.classList.contains('is-open') ? naviOpen() : naviClose();
});

window.addEventListener('resize', ()=>{
    if (mNavWrap.classList.contains('is-open')) {
        mNavWrap.classList.remove('is-open');
        naviClose();
    }
});
