        if(!document.querySelector('.bt_loadmore')) return;

        loadmore = new LoadMore({ nextBtn: '.bt_loadmore', cms: "#CMS", customScroll: { fn: null } })

        addEvent();
    }

    exports.init = init;
    return exports;
})({});

Newsroom.init();
